fn solve(a: i8, b: i8, c: i8) -> i8 {
    // Sort the sides so that x <= y <= z
    let mut sides = [a, b, c];
    sides.sort_unstable();
    let x = sides[0] as i16;
    let y = sides[1] as i16;
    let z = sides[2] as i16;

    // Check if already a non-degenerate triangle
    if x + y > z {
        0
    } else {
        // We need x + y >= z + 1 → operations = (z - (x + y) + 1)
        (z - (x + y) + 1) as i8
    }
}

